// Times the graphcalc comparison graphs in Desmos. Open
// https://www.desmos.com/calculator in Chrome, press F12, paste all of this
// into the Console and press Enter. It replaces the graph on screen, takes
// about a minute, and prints a table to compare with `graphcalc --bench-suite`.
//
// Each step waits until Desmos has finished computing and drawing (through
// asyncScreenshot), less what a screenshot of an unchanged graph costs.
// Generated by graphcalc (headless.rs, desmos_script); do not edit by hand.
(async () => {
  const FRAMES = 60;
  const GRAPHS = {
    curves: {"expressions":{"list":[{"color":"#c74440","id":"a","latex":"a=1","slider":{"hardMax":true,"hardMin":true,"max":"3","min":"0"},"type":"expression"},{"color":"#2d70b3","id":"2","latex":"L=\\left[1...40\\right]","type":"expression"},{"color":"#388c46","id":"3","latex":"y=\\frac{L}{4}-5+a\\sin\\left(Lx\\right)","type":"expression"}]},"graph":{"viewport":{"xmax":10,"xmin":-10,"ymax":6.25,"ymin":-6.25}},"randomSeed":"0","version":11},
    sums: {"expressions":{"list":[{"color":"#c74440","id":"a","latex":"a=1","slider":{"hardMax":true,"hardMin":true,"max":"3","min":"0"},"type":"expression"},{"color":"#2d70b3","id":"2","latex":"y=\\sum_{n=1}^{50}\\frac{\\sin\\left(nax\\right)}{n}","type":"expression"}]},"graph":{"viewport":{"xmax":10,"xmin":-10,"ymax":6.25,"ymin":-6.25}},"randomSeed":"0","version":11},
    implicit: {"expressions":{"list":[{"color":"#c74440","id":"a","latex":"a=1","slider":{"hardMax":true,"hardMin":true,"max":"3","min":"0"},"type":"expression"},{"color":"#2d70b3","id":"2","latex":"\\sin\\left(x^{2}+y^{2}\\right)=a\\cos\\left(xy\\right)","type":"expression"}]},"graph":{"viewport":{"xmax":10,"xmin":-10,"ymax":6.25,"ymin":-6.25}},"randomSeed":"0","version":11},
    shading: {"expressions":{"list":[{"color":"#c74440","id":"a","latex":"a=1","slider":{"hardMax":true,"hardMin":true,"max":"3","min":"0"},"type":"expression"},{"color":"#2d70b3","id":"2","latex":"\\sin\\left(x\\right)+\\cos\\left(y\\right)>a\\sin\\left(xy\\right)","type":"expression"}]},"graph":{"viewport":{"xmax":10,"xmin":-10,"ymax":6.25,"ymin":-6.25}},"randomSeed":"0","version":11},
    points: {"expressions":{"list":[{"color":"#c74440","id":"a","latex":"a=1","slider":{"hardMax":true,"hardMin":true,"max":"3","min":"0"},"type":"expression"},{"color":"#2d70b3","id":"2","latex":"n=\\left[1...5000\\right]","type":"expression"},{"color":"#388c46","id":"3","latex":"\\left(\\frac{n}{500}\\cos\\left(an\\right),\\frac{n}{500}\\sin\\left(an\\right)\\right)","type":"expression"}]},"graph":{"viewport":{"xmax":10,"xmin":-10,"ymax":6.25,"ymin":-6.25}},"randomSeed":"0","version":11},
    parametric: {"expressions":{"list":[{"color":"#c74440","id":"a","latex":"a=1","slider":{"hardMax":true,"hardMin":true,"max":"3","min":"0"},"type":"expression"},{"color":"#2d70b3","id":"2","latex":"\\left(4\\cos\\left(at\\right)+2\\cos\\left(3t\\right),4\\sin\\left(at\\right)-2\\sin\\left(5t\\right)\\right)","parametricDomain":{"max":"20\\pi","min":"0"},"type":"expression"}]},"graph":{"viewport":{"xmax":10,"xmin":-10,"ymax":6.25,"ymin":-6.25}},"randomSeed":"0","version":11},
    polar: {"expressions":{"list":[{"color":"#c74440","id":"a","latex":"a=1","slider":{"hardMax":true,"hardMin":true,"max":"3","min":"0"},"type":"expression"},{"color":"#2d70b3","id":"2","latex":"r=3+2\\cos\\left(a\\theta\\right)\\sin\\left(3\\theta\\right)","type":"expression"}]},"graph":{"viewport":{"xmax":10,"xmin":-10,"ymax":6.25,"ymin":-6.25}},"randomSeed":"0","version":11},
  };
  const size = () => Calc.graphpaperBounds.pixelCoordinates;
  const settle = () => new Promise((done) => {
    const px = size();
    Calc.asyncScreenshot({ width: px.width, height: px.height, targetPixelRatio: 1 }, () => done());
  });
  const results = [];
  for (const [graph, state] of Object.entries(GRAPHS)) {
    let t = performance.now();
    Calc.setState(state);
    await settle();
    const open = performance.now() - t;
    t = performance.now();
    for (let i = 0; i < 10; i++) await settle();
    const base = (performance.now() - t) / 10;
    const steps = async (change) => {
      const t0 = performance.now();
      for (let i = 0; i < FRAMES; i++) {
        change(i);
        await settle();
      }
      return Math.max(0, (performance.now() - t0) / FRAMES - base);
    };
    const b = Calc.graphpaperBounds.mathCoordinates;
    const bounds = (dx, k) => {
      const cx = (b.left + b.right) / 2 + dx, cy = (b.bottom + b.top) / 2;
      const hw = (b.right - b.left) / 2 / k, hh = (b.top - b.bottom) / 2 / k;
      Calc.setMathBounds({ left: cx - hw, right: cx + hw, bottom: cy - hh, top: cy + hh });
    };
    const slider = await steps((i) =>
      Calc.setExpression({ id: 'a', latex: 'a=' + (0.5 + (2 * i) / FRAMES).toFixed(4) }));
    Calc.setExpression({ id: 'a', latex: 'a=1' });
    const pan = await steps((i) => bounds((b.right - b.left) * 0.0025 * (i + 1), 1));
    const zoom = await steps((i) => bounds(0, Math.pow(1.01, i + 1)));
    const px = size();
    results.push({
      graph,
      open: +open.toFixed(1),
      slider: +slider.toFixed(1),
      pan: +pan.toFixed(1),
      zoom: +zoom.toFixed(1),
      size: px.width + 'x' + px.height,
    });
  }
  console.table(results);
  console.log('Desmos times in ms. Copy this line into the chat:\n' + JSON.stringify(results));
})();
